@cache  # noqa: B019
def _neighborhood(self, radius=1, include_center=False):
    if radius < 1:
        raise ValueError("radius must be larger than one")
    if radius == 1:
        neighborhood = {neighbor: neighbor.agents for neighbor in self._connections.values()}
        if not include_center:
            return neighborhood
        else:
            neighborhood[self] = self.agents
            return neighborhood
    else:
        neighborhood = {}
        for neighbor in self._connections.values():
            neighborhood.update(
                neighbor._neighborhood(radius - 1, include_center=True)
            )
        if not include_center:
            neighborhood.pop(self, None)
        return neighborhood

